def get_prompts_by_niche(niche: str) -> list[dict]:
    """Return all prompts for a specific niche."""
    return [p for p in PROMPTS if p.get("niche") == niche]


def get_all_niches() -> list[str]:
    """Return list of all unique niches."""
    return list(set(p.get("niche", "general") for p in PROMPTS))


def get_prompt_count() -> int:
    """Return total number of prompts."""
    return len(PROMPTS)
